const nums = (s) => s.split(' ').map(Number);
export const FY0 = 1950, FY1 = 2023;
/** Five-year age groups of childbearing as the UN tabulates them: 10–14, …, 50–54 (mid-points 12.5 … 52.5). */
export const FAGES = [10, 15, 20, 25, 30, 35, 40, 45, 50];
export const FMID = FAGES.map((a) => a + 2.5);
export const FLAB = ['10–14', '15–19', '20–24', '25–29', '30–34', '35–39', '40–44', '45–49', '50–54'];
export const NG = 9;
export const FCTRY = Object.keys(RAWF);
/** SRB-only countries (sex ratio at birth, births) in addition to the ten of chapter 3. */
export const XCTRY = { KOR: 'South Korea', ARM: 'Armenia', AZE: 'Azerbaijan', GEO: 'Georgia', VNM: 'Viet Nam', ALB: 'Albania' };
export const SRBNAME = { ...CNAME, ...XCTRY };
const _f = {}, _w = {}, _d = {};
/** Age-specific fertility rates (births per woman-year) of the nine groups 10–14 … 50–54, country c, year y (UN WPP 2024, 1950–2023). */
export function asfr(c, y) { const a = (_f[c] = _f[c] || nums(RAWF[c])); const i = (y - FY0) * NG; return a.slice(i, i + NG).map((x) => x / 1000); }
/** Women (thousands) in the nine groups, recovered as births / rate (0 where the rate is 0). */
export function women(c, y) { const a = (_w[c] = _w[c] || nums(RAWW[c])); const i = (y - FY0) * NG; return a.slice(i, i + NG); }
/** Published indicators per year 1950–2023: tfr, nrr, mac, srb (boys per 100 girls), b (births, thousands). */
export function ind(c, key) { const k = c + key; return (_d[k] = _d[k] || nums(RAWD[c][key])); }
export const indAt = (c, key, y) => ind(c, key)[y - FY0];
/** TFR from the groups: 5 Σ f. */
export const tfrOf = (f) => 5 * f.reduce((s, x) => s + x, 0);
/** Mean age of the schedule Σ a f / Σ f with mid-point ages. */
export function macOf(f) { let s = 0, t = 0; for (let i = 0; i < f.length; i++) { s += f[i] * FMID[i]; t += f[i]; } return s / t; }
/** Hutterite marital fertility rates for 15–19 … 45–49 (Coale1965, p.209 Table1; teenage0.300 is a deliberate substituted standard, p.205), padded with zeros for 10–14 and 50–54. */
export const HUT = [0, 0.3, 0.55, 0.502, 0.447, 0.406, 0.222, 0.061, 0];
/** Piecewise-linear interpolation of ys over mid-points xs, falling to zero half a group beyond the ends. */
export function lerpAt(xs, ys, x) {
  const n = xs.length;
  if (x <= xs[0]) return x <= xs[0] - 2.5 ? 0 : ys[0] * (1 - (xs[0] - x) / 2.5);
  if (x >= xs[n - 1]) return x >= xs[n - 1] + 2.5 ? 0 : ys[n - 1] * (1 - (x - xs[n - 1]) / 2.5);
  let i = 0; while (xs[i + 1] < x) i++;
  const t = (x - xs[i]) / (xs[i + 1] - xs[i]); return ys[i] * (1 - t) + ys[i + 1] * t;
}
/** Girl's survival for country c in a table year y of SEXY (female UN life table): L_a / l_0 for the nine groups, survivorship at the group mid-points, and l(30). */
export function femSurv(c, y) {
  const l = lxSex(c, 'f', y), L = LxSex(c, 'f', y), l0 = l[0];
  // 22 groups: index 3 = age 10 … 11 = age 50
  const Lg = FAGES.map((a, i) => L[3 + i] / l0);
  const lmid = Lg.map((x) => x / 5);
  return { l, L, Lg, lmid, l30: l[7] / l0, l0 };
}
/** Net reproduction rate Σ f_a (L_a/l_0) / (1 + SRB), with the sex ratio at birth srb as boys per girl. */
export const nrrOf = (f, Lg, srb) => f.reduce((s, x, i) => s + x * Lg[i], 0) / (1 + srb);
export const FYEARS = Array.from({ length: FY1 - FY0 + 1 }, (_, i) => FY0 + i);

// ───────────── drawing and model helpers (chapter 4) ─────────────
import { AGE22, CTRY } from './ch03.shared.js';
export const cOpts = (list = CTRY) => list.map((c) => ({ value: c, label: CNAME[c] }));
/** Outline of a step schedule over the nine groups: [[a, 0], [a, f], [a+5, f], …]. */
export function stepPath(f, scale = 1) {
  const pts = [[FAGES[0], 0]];
  for (let i = 0; i < f.length; i++) { pts.push([FAGES[i], f[i] * scale]); pts.push([FAGES[i] + 5, f[i] * scale]); }
  pts.push([FAGES[f.length - 1] + 5, 0]);
  return pts;
}
/** Survivorship l(a)/l(0) at any age by linear interpolation of the 22 abridged-table knots (l = array of 22 survivors). */
export function lAtAge(l, a) {
  if (a <= 0) return 1;
  for (let i = 0; i < 21; i++) if (a < AGE22[i + 1]) return (l[i] + ((l[i + 1] - l[i]) * (a - AGE22[i])) / (AGE22[i + 1] - AGE22[i])) / l[0];
  return l[21] / l[0];
}
/** Index of the group a (10, 15, …) in the nine-group arrays. */
export const gIdx = (a) => (a - 10) / 5;
